// Clase concreta que modela integraciones de billeteras virtuales (PayPal, etc.) bajo el mismo patrón polimórfico
public class ProveedorLogisticaEnvio extends AbstractIntegracion implements Consultable, Documentable {
    private String zonaCobertura;
    public ProveedorLogisticaEnvio(String id, String nombre, String estado, double latencia, String zona, boolean ultimaMilla) {
        super(id, nombre, estado, latencia);
        this.zonaCobertura = zona;
    }


    @Override
    public String mostrarDetalles() {
        return "Logística Envíos [" + identificador + "] - Zona: " + zonaCobertura;
    }

    @Override
    public String consultarEstado() { 
        return estadoConexion; 
    }

    @Override
    public double cotizar(String detalleServicio) { 
        return 120.0; 
    }

    @Override
    public double cotizarMonto(double monto) { 
        return monto + 120.0; // Suma costo base del envío al monto del paquete
    }

    @Override
    public String generarDocumento() { 
        return "Guía de Envío Generada para zona: " + zonaCobertura; 
    }
}